-- Classement des clubs (onglet UEFA) et des pays (onglet PAYS) du fichier Excel source,
-- coefficient UEFA : colonnes reprises telles quelles ("meme lignes, memes colonnes que
-- le fichier", cf. README section 8), a une exception pres : la colonne "PTS 2027" (saison
-- en cours) n'est PAS stockee comme un total fige. Elle est recalculee a la volee par
-- UefaRankingService a partir des matchs "PHASE DE LIGUE" LDC/EL/EC deja saisis dans
-- l'appli (victoire = 2 pts, nul = 1 pt, defaite = 0 pt) : au moment de l'import, ces
-- memes matchs sont deja ceux qui ont produit la valeur "PTS 2027" du fichier Excel (verifie
-- club par club), donc l'additionner en plus aurait double-compte les points. La colonne
-- points_2027_imported garde la valeur du fichier a titre d'audit/comparaison uniquement
-- (voir import/extract_uefa_rankings.py pour le detail).
CREATE TABLE club_uefa_ranking (
    id                    BIGSERIAL PRIMARY KEY,
    uefa_rank             INT           NOT NULL,
    team_id               BIGINT        REFERENCES team(id),
    club_name             VARCHAR(150)  NOT NULL,
    country               VARCHAR(60),
    current_cup           VARCHAR(10),
    total                 NUMERIC,
    points_2027_imported  NUMERIC,
    points_2026           NUMERIC,
    points_2025           NUMERIC,
    points_2024           NUMERIC,
    points_2023           NUMERIC
);
CREATE INDEX idx_club_uefa_ranking_team ON club_uefa_ranking(team_id);

CREATE TABLE country_uefa_ranking (
    id                    BIGSERIAL PRIMARY KEY,
    uefa_rank             INT           NOT NULL,
    country               VARCHAR(60)   NOT NULL UNIQUE,
    total                 NUMERIC,
    points_2027_imported  NUMERIC,
    points_2026           NUMERIC,
    points_2025           NUMERIC,
    points_2024           NUMERIC,
    points_2023           NUMERIC,
    -- Nombre de clubs encore engages, par coupe d'Europe : "now" = au moment de l'export
    -- Excel, "debut" = au tirage au sort initial de la saison. Determine la couleur
    -- (bleu/orange/jaune/rouge) affichee cote frontend (cf. CountryUefaRankingDto).
    ldc_now               INT,
    el_now                INT,
    ec_now                INT,
    ldc_debut             INT,
    el_debut              INT,
    ec_debut              INT,
    nb_2027               INT,
    nb_2026               INT,
    nb_2025               INT,
    nb_2024               INT,
    nb_2023               INT
);

-- Classement des clubs (onglet UEFA) et des pays (onglet PAYS), coefficient UEFA.
-- Genere par import/extract_uefa_rankings.py, ne pas editer a la main.
